package com.householdfinance.finance.domain; import java.math.*; import java.util.*; public record Money(BigDecimal amount,Currency currency){public Money{Objects.requireNonNull(amount);Objects.requireNonNull(currency);amount=amount.stripTrailingZeros();}public static Money of(BigDecimal a,String c){return new Money(a,Currency.getInstance(c));}public static Money zero(Currency c){return new Money(BigDecimal.ZERO,c);}public String getCurrencyCode(){return currency.getCurrencyCode();}private void same(Money o){if(!currency.equals(o.currency))throw new DomainException("Currency mismatch");}public Money add(Money o){same(o);return new Money(amount.add(o.amount),currency);}public Money subtract(Money o){same(o);return new Money(amount.subtract(o.amount),currency);}public int compareTo(Money o){same(o);return amount.compareTo(o.amount);}public boolean isPositive(){return amount.signum()>0;}}
